const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const provider = String(ai.provider || 'openai').trim().toLowerCase();
const bases = { openai: 'https://api.openai.com/v1', gemini: 'https://generativelanguage.googleapis.com/v1beta/openai', glm: 'https://api.z.ai/api/paas/v4' };
if (!bases[provider]) throw new Error('provider_not_supported');
const apiKey = String(ai.apiKey || '').trim();
if (!apiKey) throw new Error('api_key_required');
const model = String(ai.model || '').trim();
if (!model) throw new Error('model_required');
let temperature = Number(ai.temperature);
if (!Number.isFinite(temperature)) temperature = 0.2;
temperature = Math.max(0, Math.min(1, temperature));
const system = String(body.systemMessage || '').trim();
const messages = [];
if (system) messages.push({ role: 'system', content: system });
for (const item of (Array.isArray(body.history) ? body.history : [])) {
  const role = String((item || {}).role || '').trim().toLowerCase();
  const content = String((item || {}).content || '').trim();
  if ((role === 'user' || role === 'assistant') && content) messages.push({ role, content });
}
messages.push({ role: 'user', content: String(body.question || '').trim() });
const requestBody = { model, messages };
if (!(provider === 'openai' && /^gpt-5(?:-|$)/i.test(model))) requestBody.temperature = temperature;
return [{ json: { baseUrl: bases[provider], apiKey, requestBody, topic: String(body.topic || '') } }];

let response = $input.first().json || {};
if (Array.isArray(response)) response = response[0] || {};
const answer = String((((response.choices || [])[0] || {}).message || {}).content || '').trim();
if (!answer) throw new Error('empty_ai_response');
const topic = String($('Preparar conversa').first().json.topic || '');
return [{ json: { answer, topic } }];
